insert into public.questions_competence (competence_id, question, options, correct_index, explanation, difficulty, type) values
('C1a','Tu veux mettre le clignotant. Quel commodo ?','["Celui de droite", "Celui de gauche", "Le bouton au centre"]'::jsonb,1,'Mémo de pro : clignotant à gauche, balais à droite. Tu ne te trompes plus.',2,'post_validation'),
('C1a','Tu veux essuyer le pare-brise. Tu actionnes quoi ?','["Le commodo de droite", "Le commodo de gauche", "L''appel de phares"]'::jsonb,0,'Droite = essuie-glaces et lave-glace. La gauche, c''est pour tes clignotants.',2,'post_validation'),
('C1a','Contact mis, un témoin reste allumé après le test. Tu fais quoi ?','["Tu attends et tu le signales", "Tu pars, ça passera", "Tu coupes les phares"]'::jsonb,0,'Un témoin qui reste allumé (huile, frein, batterie) signale un vrai défaut.',2,'consolidation'),
('C1a','Avant de monter, ton tout premier réflexe ?','["Démarrer le moteur", "Régler la radio", "Un tour rapide de la voiture"]'::jsonb,2,'Rien sous les roues, pneus, feux et plaques propres : dix secondes qui sauvent.',2,'consolidation'),
('C1b','Pourquoi garder la jambe gauche un peu pliée en réglant le siège ?','["Pour le confort du genou", "Pour débrayer à fond", "Pour mieux voir la route"]'::jsonb,1,'Jambe tendue = embrayage pas enfoncé à fond, et tu cales sans comprendre.',2,'post_validation'),
('C1b','Tu règles le rétroviseur intérieur. Tu te penches ?','["Oui, pour mieux voir", "Tu inclines la tête", "Non, dos et épaules collés au siège"]'::jsonb,2,'Il doit montrer toute la lunette arrière sans que tu bouges de ta place.',2,'post_validation'),
('C1b','La ceinture doit passer où sur le buste ?','["Sur l''épaule, jamais sur le cou", "Au plus près du cou", "Sous le bras"]'::jsonb,0,'Sur l''épaule et sur le bassin, à plat, jamais vrillée. Sinon elle protège mal.',2,'consolidation'),
('C1b','Comment vérifier vite si ta hauteur de siège est bonne ?','["Tu baisses le pare-soleil", "Tu touches le plafond", "Tu regardes le capot"]'::jsonb,0,'Si tu vois la route sous le pare-soleil baissé, ta hauteur de regard est bonne.',2,'consolidation'),
('C1c','Où places-tu tes mains sur le volant ?','["En haut, à midi", "À 9h15, comme un quart à trois", "Une seule main suffit"]'::jsonb,1,'Pouces posés sur la jante : tu gardes précision et force pour réagir vite.',2,'post_validation'),
('C1c','Tu viens de braquer à fond à droite. Tu remets droit comment ?','["Au feeling", "L''inverse exact : un tour et demi à gauche", "Tu lâches le volant"]'::jsonb,1,'Un volant fait environ un tour et demi de chaque côté. Tu refais l''inverse.',2,'post_validation'),
('C1c','En marche arrière, tu ne sais plus de quel côté tourner. Le repère ?','["Tu tournes vers où tu veux que la voiture aille", "Tu tournes à l''opposé", "Tu regardes devant"]'::jsonb,0,'Même logique en avant et en arrière : ça évite de te mélanger droite-gauche.',2,'consolidation'),
('C1c','La voiture part doucement de travers en manœuvre. Tu fais quoi ?','["Plein de coups de volant", "Tu accélères pour rattraper", "Tu ralentis, observes, corriges doux"]'::jsonb,2,'Les coups de volant à répétition te perdent. Ralentir d''abord, corriger ensuite.',2,'consolidation'),
('C1d','Tu démarres. Quel est le tempo de l''embrayage ?','["Tout lâcher d''un coup", "Débraye, trouve le patinage, glisse doux", "Accélérer à fond d''abord"]'::jsonb,1,'Ce qui fait caler, c''est de lâcher l''embrayage d''un coup au patinage.',2,'post_validation'),
('C1d','Pourquoi un filet d''accélérateur au démarrage ?','["Pour faire du bruit", "Pour donner de la force au moteur", "Ce n''est pas utile"]'::jsonb,1,'La voiture pèse une tonne : sans un peu de gaz au démarrage, tu cales.',2,'post_validation'),
('C1d','Tu freines pour t''arrêter complètement. Quand débrayes-tu ?','["Juste avant l''arrêt", "Tout de suite", "Après l''arrêt"]'::jsonb,0,'Trop tôt = roue libre, trop tard = tu cales pile avant de t''arrêter.',2,'consolidation'),
('C1d','Talon décollé, semelle qui glisse sur la pédale : quel risque ?','["Aucun, c''est pareil", "Tu perds le point de patinage", "Tu freines plus fort"]'::jsonb,1,'Talon ancré au sol qui glisse : tu retrouves le patinage toujours au même endroit.',2,'consolidation'),
('C1e','Un feu passe au rouge 100 m devant. Premier geste ?','["Freiner d''un coup au dernier moment", "Lâcher l''accélérateur, puis freiner doux", "Garder le gaz"]'::jsonb,1,'Le frein moteur fait déjà une partie du travail. Tu anticipes, tu ne piles pas.',2,'post_validation'),
('C1e','C''est quoi le freinage dégressif en deux temps ?','["Freiner fort jusqu''au bout", "Pomper la pédale", "Fort pour ralentir, léger pour retenir"]'::jsonb,2,'On relâche juste avant l''arrêt : pas de à-coup, passagers pas secoués.',2,'post_validation'),
('C1e','Rouler en accordéon (accélérer fort, freiner fort, en boucle), pourquoi c''est nul ?','["Ça va plus vite", "On regarde trop près, on fatigue tout le monde", "C''est plus sûr"]'::jsonb,1,'Regarde loin : tu vois les ralentissements arriver et tu lisses ta conduite.',2,'consolidation'),
('C1e','Comment travailler le dosage de l''accélérateur ?','["Se stabiliser à différents régimes", "En appuyant à fond", "Seulement en roulant vite"]'::jsonb,0,'Tu vises un régime, et si tu dépasses tu soulages un peu sans lâcher. Même à l''arrêt.',2,'consolidation'),
('C1f','Tu changes de vitesse. Tu regardes où ?','["Le levier", "La route, toujours", "Le compteur"]'::jsonb,1,'Tu sens les rapports à la main, paume sur le pommeau, sans quitter la route.',2,'post_validation'),
('C1f','Comment tiens-tu le levier de vitesses ?','["Du bout des doigts", "Serré très fort", "Paume posée sur le pommeau, sans forcer"]'::jsonb,2,'C''est la position de la main qui compte, pas la force. Une erreur de boîte est éliminatoire.',2,'post_validation'),
('C1f','Virage serré devant. Tu rétrogrades avant ou pendant ?','["Pendant le virage", "Avant, une fois ralenti", "Après le virage"]'::jsonb,1,'On rétrograde parce qu''on a déjà ralenti, pour avoir de la reprise en sortie.',2,'consolidation'),
('C1f','Tu t''arrêtes à un stop. En quelle vitesse ?','["En 1ère", "En 2e", "Au point mort"]'::jsonb,1,'On s''arrête en 2e, puis on repasse la 1ère pour repartir. Plus fluide.',2,'consolidation'),
('C1g','Sur un pneu, tu vérifies quoi à l''œil avant de partir ?','["Dégonflé, coupure, gomme usée", "La couleur de la jante", "La marque du pneu"]'::jsonb,0,'Un pneu lisse ou abîmé freine mal et peut éclater. Regarde le témoin d''usure.',2,'post_validation'),
('C1g','L''inspecteur : montrez la commande des feux de croisement. Tu fais quoi ?','["Tu récites par cœur", "Tu la désignes et l''actionnes", "Tu expliques sans toucher"]'::jsonb,1,'On montre, on ne récite pas : tu désignes le commodo de gauche et tu l''actionnes.',2,'post_validation'),
('C1g','Pourquoi vérifier ses feux avant de rouler ?','["Pour la déco", "Un feu mort = tu n''es pas vu", "Ça consomme moins"]'::jsonb,1,'Clignotant ou stop en panne : les autres ne lisent plus tes intentions. Danger direct.',2,'consolidation'),
('C1g','À l''examen, le tour de voiture, c''est quoi exactement ?','["Réciter une longue liste", "Juste regarder les pneus", "Une vérif + sécurité + premiers secours"]'::jsonb,2,'Tu montres l''élément (le bouchon d''huile est ici) et tu fais le geste, calmement.',2,'consolidation'),
('C1h','La règle d''or de toute manœuvre lente comme le créneau ?','["Aller très lentement", "Aller vite pour finir", "Braquer le plus tard possible"]'::jsonb,0,'Tu n''es pas chronométré : la lenteur te donne le temps de braquer et corriger.',2,'post_validation'),
('C1h','Tu peux t''appuyer sur le trottoir en manœuvre. Et monter dessus ?','["Oui, si c''est doux", "Non, taper ou monter = ajournement", "Seulement avec la roue arrière"]'::jsonb,1,'T''appuyer doucement, oui. Monter ou taper le trottoir, c''est éliminé direct.',2,'post_validation'),
('C1h','Bataille arrière : quel repère vises-tu en te retournant ?','["Le 2e feu de la voiture voisine", "Le premier feu, vers le début de la lunette", "Le pare-chocs avant"]'::jsonb,1,'Si tu vises le 2e feu, tu t''écartes trop. Premier feu = bonne trajectoire.',2,'consolidation'),
('C1h','En manœuvre, es-tu prioritaire sur les autres usagers ?','["Oui, tu manœuvres", "Non, jamais : tu laisses passer", "Seulement la nuit"]'::jsonb,1,'Tu sécurises avant, contrôles à 360, et tu laisses passer tout le monde.',2,'consolidation'),
('C1i','Tu rates le début d''un créneau. Bon réflexe ?','["Forcer pour rentrer quand même", "Te remettre droit, repérer l''espace, corriger", "Tout recommencer en panique"]'::jsonb,1,'Volant droit, roues droites, tu ramènes la voiture du côté où tu as de la place.',2,'post_validation'),
('C1i','Comment savoir qu''une manœuvre est vraiment acquise ?','["Quand le moniteur te guide bien", "Quand tu vas vite", "Quand tu la fais seul, sans guidage"]'::jsonb,2,'Si tu attends le top du moniteur à chaque geste, ce n''est pas encore acquis.',2,'post_validation'),
('C1i','Avant de te lancer en manœuvre autonome, premier geste de sécurité ?','["Accélérer", "Clignotant + contrôles (rétros, angle mort)", "Klaxonner"]'::jsonb,1,'On sécurise avant de bouger, et on n''est jamais prioritaire en manœuvre.',2,'consolidation'),
('C1i','Créneau à gauche : quand est-ce permis ?','["Toujours, peu importe la rue", "Uniquement en sens unique", "Jamais"]'::jsonb,1,'À gauche hors sens unique, tu te mets à contre-sens. Choisis bien le côté.',2,'consolidation'),
('C2a','Tu roules en ville sur une ligne droite. Où poses-tu ton regard ?','["Loin devant, à mi-hauteur du pare-brise", "Sur le capot de ta voiture", "Sur la voiture juste devant toi"]'::jsonb,0,'Le regard loin te donne le temps d''anticiper au lieu de subir.',2,'post_validation'),
('C2a','À quelle fréquence reviens-tu au rétro intérieur ?','["Une fois en arrivant, c''est suffisant", "Seulement avant de freiner", "Toutes les 5 à 7 secondes environ"]'::jsonb,2,'Savoir qui te suit te prépare à freiner ou changer de voie sans surprise.',2,'post_validation'),
('C2a','Une balle traverse la route à 50 m devant toi. Ton réflexe ?','["Klaxonner pour prévenir", "Lever le pied et balayer les trottoirs des yeux", "Continuer, elle est déjà passée"]'::jsonb,1,'Derrière une balle, il y a souvent un enfant qui court après.',2,'consolidation'),
('C2a','Pour bien photographier la scène, tu bouges quoi ?','["Seulement les yeux", "La tête, pas seulement les yeux", "Rien, tu fixes droit devant"]'::jsonb,1,'Tourner la tête te fait voir les entrées de garage et les rues qui débouchent.',2,'consolidation'),
('C2b','Tu approches d''une école, enfants sur le trottoir, et tu es sous la limite. Tu fais quoi ?','["Tu lèves quand même le pied", "Tu gardes ta vitesse, tu es dans la limite", "Tu accélères pour passer vite"]'::jsonb,0,'La limite est un maximum, pas une obligation : la bonne vitesse dépend du risque réel.',2,'post_validation'),
('C2b','Comment vérifies-tu ta distance avec la voiture de devant ?','["À l''œil, une longueur de voiture", "Tant que tu vois ses feux, c''est bon", "La règle des 2 secondes sur un repère fixe"]'::jsonb,2,'Deux secondes, c''est ta marge pour freiner si elle s''arrête net.',2,'post_validation'),
('C2b','Il pleut. Quelle distance laisses-tu avec celui de devant ?','["La même qu''au sec", "Tu doubles : au moins 4 secondes", "Tu réduis pour mieux le voir"]'::jsonb,1,'Sur sol mouillé, ta distance de freinage explose : double la marge.',2,'consolidation'),
('C2b','Tu descends une pente assez raide. Tu gères ta vitesse comment ?','["Tu lâches l''accélérateur et laisses le relief te ralentir", "Tu continues d''accélérer pour rester souple", "Tu freines fort en continu"]'::jsonb,0,'Accélérer en descente, c''est prendre de la vitesse pour rien et freiner plus fort après.',2,'consolidation'),
('C2c','Tu longes des voitures garées à droite. Quelle distance ?','["Au moins une largeur de portière", "Le plus près possible pour rester à droite", "Tu colles, ça force à ralentir"]'::jsonb,0,'Une porte peut s''ouvrir ou un piéton surgir entre deux voitures.',2,'post_validation'),
('C2c','La rue te semble trop étroite pour ta voiture. Tu fais quoi ?','["Tu serres à droite à fond", "Tu t''arrêtes, ça ne passe pas", "Tu te fies à tes repères : la voie est plus large qu''il n''y paraît"]'::jsonb,2,'Une voie fait au moins 3 m, ta voiture 1,80 m : c''est un effet d''optique.',2,'post_validation'),
('C2c','Où te places-tu sur ta voie en conduite normale ?','["Collé à la bordure de droite", "Au milieu de ta voie", "À cheval sur la ligne du centre"]'::jsonb,1,'Bien centré, ta voiture est lisible et tu gardes de la marge des deux côtés.',2,'consolidation'),
('C2c','Tu croises un cycliste sur une route étroite. Tu te places comment ?','["Tu serres à droite pour l''éviter", "Tu passes au plus près, il a sa bande", "Tu te décales un peu à gauche, après avoir vérifié que c''est libre"]'::jsonb,2,'On serre vers la gauche quand c''est sûr, jamais on ne frôle le vélo.',2,'consolidation'),
('C2d','Tu abordes un virage serré. Tu freines quand ?','["Avant, sur la portion encore droite", "En plein milieu du virage", "À la sortie du virage"]'::jsonb,0,'La voiture freine bien en ligne droite ; freiner dans la courbe la déséquilibre.',2,'post_validation'),
('C2d','Dans le virage, où regardes-tu ?','["Le bord de la route, pour ne pas mordre", "Loin, vers la sortie du virage", "Le capot, pour suivre la ligne"]'::jsonb,1,'Le regard tire la trajectoire : si tu regardes le bord, tu vas vers le bord.',2,'post_validation'),
('C2d','Comment tiens-tu le volant dans un virage à gauche ?','["Tu forces des deux mains à fond", "Tu lâches et tu laisses revenir seul", "Tu tires d''une main, la gauche"]'::jsonb,2,'Tirer d''une main garde le geste souple ; forcer à deux mains crispe et déporte.',2,'consolidation'),
('C2d','À quel moment ré-accélères-tu dans un virage ?','["Dès l''entrée, pour rester dynamique", "Au point le plus serré", "À la sortie, quand la route se rouvre, en douceur"]'::jsonb,2,'Accélérer trop tôt rouvre la trajectoire et te déporte vers l''extérieur.',2,'consolidation'),
('C2e','Tu hésites à dépasser : la visibilité n''est pas parfaite. Tu fais quoi ?','["Tu y vas, ça va passer", "Tu ne dépasses pas : tu lèves le pied et tu renonces", "Tu te déportes pour mieux voir"]'::jsonb,1,'Le doute suffit à annuler le dépassement : on ne double que quand on voit loin et libre.',2,'post_validation'),
('C2e','Avant de déboîter pour dépasser, quel est le bon enchaînement de contrôles ?','["Clignotant puis on déboîte", "Un coup d''œil dans le rétro et c''est parti", "Rétro intérieur, rétro gauche, clignotant, angle mort, action"]'::jsonb,2,'Cette séquence garantit que personne n''est déjà en train de te doubler.',2,'post_validation'),
('C2e','Tu dépasses un cycliste hors agglomération. Quel écart latéral ?','["Au moins 1,50 m", "50 cm suffisent", "Tu colles pour passer vite"]'::jsonb,0,'1,50 m hors ville, 1 m en ville : un cycliste peut zigzaguer à tout moment.',2,'consolidation'),
('C2e','Tu viens de doubler une voiture. Quand te rabats-tu devant elle ?','["Dès que ton avant la dépasse", "Quand tu la vois entière dans ton rétro intérieur, clignotant droit", "Quand celui de derrière te le réclame"]'::jsonb,1,'Te rabattre trop tôt l''oblige à freiner : tu lui coupes la route.',2,'consolidation'),
('C2f','Carrefour sans aucun panneau ni feu. Qui passe en premier ?','["Celui qui arrive le plus vite", "Toi, tu continues tout droit", "Ce qui débouche de ta droite"]'::jsonb,2,'Sans signalisation, c''est la priorité à droite : tu cèdes à ce qui vient de ta droite.',2,'post_validation'),
('C2f','Comment distingues-tu un giratoire d''un rond-point ?','["À sa taille", "À l''entrée : Cédez le passage = giratoire, aucun panneau = rond-point", "À la couleur du marquage"]'::jsonb,1,'Giratoire : tu cèdes aux engagés. Rond-point : priorité à droite, l''entrant est prioritaire.',2,'post_validation'),
('C2f','Sur un giratoire, quand mets-tu ton clignotant à droite ?','["Dès l''entrée sur l''anneau", "Jamais, c''est inutile", "Juste avant ta sortie"]'::jsonb,2,'Trop tôt, le clignotant fait croire que tu sors avant et bloque les autres.',2,'consolidation'),
('C2f','Une voiture venant de ta droite ralentit pour te laisser passer, sans panneau. Tu passes ?','["Oui, elle t''a fait signe", "Non : elle est prioritaire, tu la laisses passer", "Tu accélères pour ne pas la gêner"]'::jsonb,1,'Si elle freine pour toi, c''est déjà un refus de priorité de ta part.',2,'consolidation'),
('C2g','Tu tournes à gauche dans 50 m. Quand mets-tu le clignotant ?','["Assez tôt, avant de tourner", "Pile au moment où tu tournes", "Une fois engagé dans la rue"]'::jsonb,0,'Un clignotant mis pendant le virage n''a prévenu personne.',2,'post_validation'),
('C2g','Un piéton attend au bord d''un passage protégé. Ton geste ?','["Croiser son regard et ralentir pour le laisser passer", "Klaxonner pour qu''il se décide", "Passer vite avant lui"]'::jsonb,0,'Le contact visuel lève le doute ; on ne force jamais le passage.',2,'post_validation'),
('C2g','Quelqu''un te colle et t''agace. Tu klaxonnes pour montrer ton énervement ?','["Oui, il comprendra", "Tu freines sec pour le calmer", "Non, le klaxon sert à avertir d''un danger"]'::jsonb,2,'En ville, l''usage du klaxon est même strictement limité.',2,'consolidation'),
('C2g','Tu as mis ton clignotant pour changer de voie. Que fais-tu ensuite ?','["Tu attends 50 m avant de te déporter", "Tu te places dès que c''est possible", "Tu coupes le clignotant et tu restes"]'::jsonb,1,'Signaler sans se placer entretient le doute chez ceux de derrière.',2,'consolidation'),
('C2h','Tu réalises trop tard que tu es dans la mauvaise voie au giratoire. Ton réflexe ?','["Tu changes de voie en force tout de suite", "Tu restes dans ta voie et tu refais un tour si besoin", "Tu freines net au milieu"]'::jsonb,1,'On ne change jamais de voie en force dans le trafic pour rattraper une erreur.',2,'post_validation'),
('C2h','Une camionnette de livraison bloque ta voie. Tu fais quoi ?','["Tu déboîtes vite avant qu''on arrive", "Tu klaxonnes pour qu''elle bouge", "Tu t''arrêtes, tu contrôles derrière et l''angle mort, puis tu contournes si c''est libre"]'::jsonb,2,'On traite l''obstacle comme un mini-dépassement, en sécurité.',2,'post_validation'),
('C2h','Comment sais-tu que tu maîtrises la conduite en ville ?','["Quand tu enchaînes une longue séquence sans intervention du moniteur", "Quand tu roules vite sans caler", "Quand tu connais toutes les rues"]'::jsonb,0,'Tes contrôles sont devenus automatiques : ta tête est libre pour anticiper.',2,'consolidation'),
('C2h','Avant de démarrer un trajet seul en ville, que fais-tu ?','["Tu pars et tu improvises", "Tu visualises ton itinéraire et les zones difficiles", "Tu attends d''avoir un GPS qui parle"]'::jsonb,1,'Visualiser le trajet libère ta tête pour décider au lieu de chercher ta route.',2,'consolidation'),
('C3a','Des phares arrivent en face la nuit. Tu regardes où ?','["Les phares d''en face", "Le bord droit de ta voie", "Le centre de la route"]'::jsonb,1,'Fixer les phares t''éblouit ; le bord droit te garde dans ta trajectoire.',2,'post_validation'),
('C3a','Route déserte, une lueur de phares apparaît au loin. Ton geste ?','["Repasser en feux de croisement", "Rester pleins phares", "Faire un appel de phares"]'::jsonb,0,'On baisse dès qu''on perçoit quelqu''un, même une simple lueur, pour ne pas l''éblouir.',2,'post_validation'),
('C3a','La nuit, un doute sur un piéton sombre devant toi. Tu fais quoi ?','["Tu accélères pour passer", "Tu klaxonnes et tu fonces", "Tu lèves le pied et tu vérifies"]'::jsonb,2,'Certitude = action, doute = pas de vitesse : un piéton foncé se voit très tard.',2,'consolidation'),
('C3a','Tu sens tes paupières tomber au volant la nuit. La bonne réaction ?','["Tu tiens jusqu''aux 2 h de route", "Tu t''arrêtes dès le premier signe", "Tu ouvres la fenêtre et tu continues"]'::jsonb,1,'Pause toutes les 2 h, mais surtout dès le moindre signe de fatigue, sans attendre.',2,'consolidation'),
('C3b','Sous la pluie, tu multiplies ta distance de sécurité par combien ?','["Par 2", "Tu gardes la même", "Par 1,5"]'::jsonb,0,'Sol mouillé = freinage doublé : on passe de 2 à 4 secondes d''écart.',2,'post_validation'),
('C3b','Il pleut fort. Peux-tu allumer ton feu de brouillard arrière ?','["Oui, toujours sous la pluie", "Non, interdit sous la pluie", "Seulement la nuit"]'::jsonb,1,'L''arrière éblouit la voiture derrière : il est réservé au brouillard ou à la neige.',2,'post_validation'),
('C3b','Une grosse flaque barre ta voie, impossible de l''éviter. Ton geste ?','["Foncer dedans à vitesse normale", "Freiner fort dans la flaque", "Ralentir avant, traverser volant stable"]'::jsonb,2,'Foncer = aquaplaning : on ralentit avant, jamais dans la flaque, sans coup de volant.',2,'consolidation'),
('C3b','Sur autoroute limitée à 130, il se met à pleuvoir. Ta vitesse max ?','["130 km/h", "110 km/h", "120 km/h"]'::jsonb,1,'Sous la pluie le 130 passe à 110 : moins d''adhérence, on lève le pied.',2,'consolidation'),
('C3c','Tu arrives sur des feuilles mortes mouillées en sortie de virage. Ton geste ?','["Un coup de volant pour passer vite", "Lever le pied avant, volant stable", "Freiner fort dessus"]'::jsonb,1,'Les feuilles humides glissent comme du savon : tout geste brusque fait partir la voiture.',2,'post_validation'),
('C3c','Sur chaussée glissante, quand fais-tu ton freinage avant un virage ?','["En ligne droite, avant le virage", "En plein milieu du virage", "À la sortie du virage"]'::jsonb,0,'Freiner et tourner ensemble demande trop d''adhérence : on freine droit, puis on tourne pied levé.',2,'post_validation'),
('C3c','L''arrière de ta voiture part légèrement sur le verglas. En premier ?','["Coup de frein sec", "Braquer fort dans l''autre sens", "Lever le pied et viser où aller"]'::jsonb,2,'La voiture suit ton regard ; un frein sec aggrave la glissade.',2,'consolidation'),
('C3c','Tu repères une plaque luisante à l''ombre sous les arbres. Tu fais quoi ?','["Tu ralentis en douceur avant d''y être", "Tu freines une fois dessus", "Tu accélères pour passer vite"]'::jsonb,0,'On anticipe : lever le pied avant la zone glissante, jamais dessus.',2,'consolidation'),
('C3d','Freinage d''urgence sur voiture à ABS. Ton premier geste ?','["Débrayer d''abord", "Freiner à fond d''un coup", "Freiner par petits à-coups"]'::jsonb,1,'Le frein d''abord, à fond : l''embrayage vient seulement après, juste avant de caler.',2,'post_validation'),
('C3d','En freinage d''urgence, la pédale vibre fort sous ton pied. Tu fais quoi ?','["Tu relâches un peu", "Tu pompes la pédale", "Tu continues d''appuyer fort"]'::jsonb,2,'La vibration, c''est l''ABS qui travaille : relâcher allonge la distance d''arrêt.',2,'post_validation'),
('C3d','Un obstacle est pile devant toi en freinage d''urgence. Tu regardes où ?','["L''obstacle", "Ton échappatoire libre", "Tes rétroviseurs"]'::jsonb,1,'La voiture suit le regard : viser l''espace libre t''y emmène, fixer l''obstacle t''y envoie.',2,'consolidation'),
('C3d','Avec l''ABS, pendant un freinage d''urgence, peux-tu diriger la voiture ?','["Non, les roues sont bloquées", "Oui, tu freines à fond ET tu diriges", "Seulement après avoir relâché"]'::jsonb,1,'L''ABS empêche le blocage : tu gardes la direction pour éviter l''obstacle.',2,'consolidation'),
('C3e','Tu es sur la bande d''insertion de l''autoroute. Ton objectif de vitesse ?','["Ralentir pour t''insérer", "Atteindre la vitesse du flux (70-80 min)", "T''arrêter en bout de bande"]'::jsonb,1,'On s''insère dans un trou à leur allure ; arriver lentement force tout le monde à freiner.',2,'post_validation'),
('C3e','Tu viens de doubler un camion sur l''autoroute. Tu fais quoi ?','["Tu restes sur la voie de gauche", "Tu te rabats à droite", "Tu ralentis à côté de lui"]'::jsonb,1,'La voie de gauche sert à dépasser : on libère dès qu''on a doublé.',2,'post_validation'),
('C3e','Ta sortie d''autoroute approche. Quand ralentis-tu ?','["Sur la voie de circulation", "Dès que tu vois le panneau", "Une fois sur la voie de décélération"]'::jsonb,2,'On ne freine jamais sur l''autoroute : clignotant tôt, puis on ralentit sur la bretelle.',2,'consolidation'),
('C3e','Avant de t''insérer, en plus du rétro gauche, tu contrôles quoi ?','["Rien d''autre", "L''angle mort par-dessus l''épaule", "Juste le rétro intérieur"]'::jsonb,1,'Un motard ou une voiture peut se faufiler dans l''angle mort, invisible au rétro.',2,'consolidation'),
('C3f','Tu entres dans un tunnel en plein jour. Ton geste avant l''entrée ?','["Allumer les pleins phares", "Allumer les feux de croisement", "Ne rien allumer"]'::jsonb,1,'Les croisements te rendent visible sans aveugler ; jamais les pleins phares en tunnel.',2,'post_validation'),
('C3f','Dès que tu es dans le tunnel, tu repères quoi en priorité ?','["La sortie de secours la plus proche", "La station radio", "La vitesse des autres"]'::jsonb,0,'Dans un espace fermé, savoir où s''échapper change tout en cas de problème.',2,'post_validation'),
('C3f','Tu traverses un long pont exposé un jour de vent. Comment tiens-tu le volant ?','["Une main, détendu", "Tu lâches en sortie de pont", "Fermement des deux mains"]'::jsonb,2,'Le vent latéral pousse la voiture d''un coup : un volant mou = embardée.',2,'consolidation'),
('C3f','Dans un tunnel, ta voiture tombe en panne. Qu''est-ce qui est interdit ?','["Couper le moteur", "Faire demi-tour ou marche arrière", "Aller vers la sortie de secours à pied"]'::jsonb,1,'Pas de demi-tour ni marche arrière en tunnel : on coupe le moteur et on rejoint l''issue à pied.',2,'consolidation'),
('C3g','Tu vas tourner à droite en ville. En plus du rétro, tu contrôles quoi ?','["Rien d''autre", "Ton angle mort droit, par-dessus l''épaule", "Le rétro gauche seulement"]'::jsonb,1,'Un cycliste qui remonte à droite est invisible au rétro : le coup d''œil épaule évite l''accident.',2,'post_validation'),
('C3g','Un bus arrêté à droite te masque le passage piéton devant lui. Tu fais quoi ?','["Tu passes normalement", "Tu klaxonnes et tu doubles", "Tu ralentis et n''avances qu''une fois sûr"]'::jsonb,2,'Le bus cache un piéton qui peut surgir : tant que tu n''es pas certain, tu n''accélères pas.',2,'post_validation'),
('C3g','Tu dépasses un cycliste sur un boulevard urbain. Quel écart minimum ?','["Au moins 1 mètre", "50 cm suffisent", "Tu peux frôler si tu ralentis"]'::jsonb,0,'1 m en ville (1,50 m hors agglo) absorbe l''imprévu du vélo qui zigzague.',2,'consolidation'),
('C3g','Un bus redémarre de son arrêt juste devant toi. Tu fais quoi ?','["Tu accélères pour passer avant lui", "Tu lèves le pied et tu le laisses repartir", "Tu klaxonnes pour qu''il attende"]'::jsonb,1,'Le bus qui quitte son arrêt est prioritaire : on lui laisse la place.',2,'consolidation'),
('C4a','Avant un long trajet inconnu, tu fais quoi ?','["Tu pars au feeling, tu verras", "Tu regardes l''itinéraire entier et repères 2-3 points", "Tu programmes le GPS en roulant"]'::jsonb,1,'Ce qui se prépare à l''arrêt libère ton attention pour la route.',2,'post_validation'),
('C4a','Le GPS, tu le règles quand ?','["Voiture à l''arrêt, avant de démarrer", "Au premier feu rouge", "Dès que tu roules"]'::jsonb,0,'2 secondes les yeux baissés à 90 km/h, c''est 50 m à l''aveugle.',2,'post_validation'),
('C4a','4 heures de route. Tes pauses ?','["Aucune si tu te sens en forme", "Une seule à mi-parcours", "Environ 15 min toutes les 2 heures"]'::jsonb,2,'La fatigue arrive sans prévenir : la pause régulière, c''est de la sécurité.',2,'consolidation'),
('C4a','Une route est annoncée coupée. Le bon réflexe ?','["Avoir prévu un itinéraire de secours", "Forcer le passage", "Improviser sur place"]'::jsonb,0,'Un plan B préparé t''évite de chercher ta sortie en panique.',2,'consolidation'),
('C4b','Le GPS dit gauche, mais le panneau indique sens interdit. Tu suis quoi ?','["Le GPS, il connaît la route", "La signalisation, toujours", "Tu t''arrêtes pour réfléchir"]'::jsonb,1,'Le GPS peut être périmé : ce que tu vois sur la route gagne toujours.',2,'post_validation'),
('C4b','Tu rates ta sortie d''autoroute. Tu fais quoi ?','["Tu freines pour te rabattre", "Tu fais une courte marche arrière", "Tu continues jusqu''à la sortie suivante"]'::jsonb,2,'Une sortie ratée coûte 10 minutes, pas ta vie : jamais de recul sur autoroute.',2,'post_validation'),
('C4b','Ta ville est tout en bas du panneau d''autoroute. Ça signifie ?','["Ta sortie est la prochaine", "Ta sortie est encore loin", "Tu t''es trompé de direction"]'::jsonb,0,'Plus le nom est bas, plus la sortie est proche : place-toi à droite tôt.',2,'consolidation'),
('C4b','Tu dois changer de plusieurs voies pour ta sortie. Quand t''y prendre ?','["Au dernier moment, d''un coup", "Le plus tôt possible, en douceur", "En forçant le rabattement"]'::jsonb,1,'Tu prends l''info tôt (rétros, clignotant) et tu glisses sans perdre de vitesse.',2,'consolidation'),
('C4c','En éco-conduite, tu passes tes rapports tôt ou tard ?','["Tard, pour avoir de la puissance", "Tôt, pour rouler bas régime", "Toujours en 2e en ville"]'::jsonb,1,'Un moteur bas régime consomme moins, fait moins de bruit et s''use moins.',2,'post_validation'),
('C4c','Un feu rouge à 100 m. Le geste le plus éco ?','["Garder l''allure puis freiner sec", "Accélérer pour passer", "Lever le pied tôt et laisser ralentir"]'::jsonb,2,'Le frein moteur évite de gaspiller le carburant que tu viens de brûler.',2,'post_validation'),
('C4c','Une conduite souple, ça économise combien de carburant ?','["Quelques gouttes, négligeable", "Jusqu''à environ 20 %", "Plus de la moitié"]'::jsonb,1,'La souplesse est le levier n°1 de l''éco-conduite, avant même la voiture.',2,'consolidation'),
('C4c','Belle ligne droite dégagée. En éco-conduite tu fais quoi ?','["Tu montes en 5e ou 6e", "Tu restes en 3e pour la reprise", "Tu accélères par à-coups"]'::jsonb,0,'Le rapport élevé en bas régime, c''est ce qui consomme le moins.',2,'consolidation'),
('C4d','Pour anticiper les dangers, où porte ton regard ?','["Sur le capot, juste devant", "Loin devant, en balayant rétros et côtés", "Fixe sur la voiture qui précède"]'::jsonb,1,'Plus tu vois loin, plus tu as de temps pour décider sans paniquer.',2,'post_validation'),
('C4d','Une voiture te colle et klaxonne. Tu fais quoi ?','["Tu freines pour la punir", "Tu accélères au-dessus de la limite", "Tu restes calme et la laisses dépasser"]'::jsonb,2,'Répondre à l''agressivité crée le risque ; rester posé le désamorce.',2,'post_validation'),
('C4d','Intersection sans visibilité, cachée par des voitures garées. Tu fais quoi ?','["Tu avances doucement, pied prêt à freiner", "Tu passes, rien vu", "Tu accélères pour passer vite"]'::jsonb,0,'La conscience du danger, c''est sentir le risque AVANT de le voir.',2,'consolidation'),
('C4d','La distance de sécurité par temps sec, c''est la règle des ?','["2 secondes (4 sous la pluie)", "1 mètre fixe", "10 secondes toujours"]'::jsonb,0,'2 s avec la voiture devant, doublé à 4 s quand la chaussée est mouillée.',2,'consolidation'),
('C4e','Tu dépasses un cycliste en ville. Quel écart ?','["Au moins 1 mètre", "Au ras, ça passe", "30 centimètres"]'::jsonb,0,'1 m en ville, 1,5 m hors agglo : la marge s''il fait un écart soudain.',2,'post_validation'),
('C4e','Un piéton attend au bord d''un passage piéton. Tu fais quoi ?','["Tu passes tant qu''il n''a pas un pied dessus", "Tu t''arrêtes, il est déjà prioritaire", "Tu klaxonnes pour qu''il attende"]'::jsonb,1,'Passer devant un piéton qui veut traverser, le jour J, c''est éliminatoire.',2,'post_validation'),
('C4e','Route trop étroite pour laisser 1 m au cycliste. Tu fais quoi ?','["Tu doubles serré quand même", "Tu klaxonnes pour qu''il se range", "Tu patientes derrière jusqu''à pouvoir doubler"]'::jsonb,2,'Le dépassement serré par impatience, c''est l''accident vélo le plus fréquent.',2,'consolidation'),
('C4e','Ton feu est vert, celui du piéton est rouge. Tu t''arrêtes pour le laisser ?','["Non, c''est un arrêt injustifié et dangereux", "Oui, par politesse", "Tu klaxonnes et tu passes"]'::jsonb,0,'S''arrêter pour qui n''est PAS prioritaire est une faute : tu suis ta priorité.',2,'consolidation'),
('C4f','L''inspecteur demande les deux derniers chiffres du totaliseur. Pourquoi ?','["Pour vérifier ton kilométrage", "Pour tirer le numéro de tes 3 questions", "Pour noter la date"]'::jsonb,1,'Ça désigne 3 questions cadeau : vérification, sécurité routière, premiers secours.',2,'post_validation'),
('C4f','Tu cales au démarrage pendant l''examen. C''est terminé ?','["Oui, c''est éliminatoire", "Non, tu redémarres calmement", "Tu abandonnes l''examen"]'::jsonb,1,'Une petite erreur ne fait pas échouer : l''inspecteur regarde ta capacité à te corriger.',2,'post_validation'),
('C4f','Les 3 questions de l''examen portent sur quoi ?','["Vérification, sécurité routière, premiers secours", "Code, panneaux, mécanique", "Itinéraire, météo, GPS"]'::jsonb,0,'Chaque bonne réponse vaut 1 point : tu peux louper le permis à 1 point près.',2,'consolidation'),
('C4f','Manœuvre demandée à l''examen. Le réflexe juste ?','["Vite, pour montrer que tu maîtrises", "Lentement, regard partout, clignotant avant", "Sans clignotant, c''est juste une manœuvre"]'::jsonb,1,'Tu mets le clignotant AVANT de t''arrêter pour la manœuvre, pas après.',2,'consolidation'),
('C4g','Permis classique en poche. Vitesse max sur autoroute ?','["130 km/h comme tout le monde", "110 km/h", "90 km/h"]'::jsonb,1,'En probatoire : 110 autoroute, 100 voie rapide, 80 route, les 3 premières années.',2,'post_validation'),
('C4g','Le disque A à l''arrière, tu le gardes combien de temps ?','["3 ans (2 ans si conduite accompagnée)", "6 mois", "À vie"]'::jsonb,0,'Il prévient les autres que tu débutes, pour qu''ils te laissent de la marge.',2,'post_validation'),
('C4g','Tu démarres ton permis probatoire avec combien de points ?','["12 points d''office", "6 points qui montent à 12", "0 point au départ"]'::jsonb,1,'6 points au départ : une grosse infraction peut tout faire sauter.',2,'consolidation'),
('C4g','Le taux d''alcool max en jeune permis, c''est ?','["0,5 g/l comme les autres", "0,2 g/l (en pratique, zéro)", "Aucune limite"]'::jsonb,1,'0,2 g/l, donc en clair tu ne bois pas si tu conduis.',2,'consolidation');
